ALTER TABLE nodes ADD COLUMN IF NOT EXISTS name TEXT, ADD COLUMN IF NOT EXISTS version TEXT, ADD COLUMN IF NOT EXISTS hostname TEXT, ADD COLUMN IF NOT EXISTS os TEXT, ADD COLUMN IF NOT EXISTS kernel TEXT, ADD COLUMN IF NOT EXISTS architecture TEXT, ADD COLUMN IF NOT EXISTS cpu_count INTEGER, ADD COLUMN IF NOT EXISTS memory_bytes BIGINT;
ALTER TABLE assets ADD COLUMN IF NOT EXISTS description TEXT NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS hardware_type TEXT NOT NULL DEFAULT 'generic-linux', ADD COLUMN IF NOT EXISTS capabilities JSONB NOT NULL DEFAULT '{}'::jsonb, ADD COLUMN IF NOT EXISTS labels JSONB NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE assets DROP CONSTRAINT IF EXISTS assets_status_check;
ALTER TABLE assets ADD CONSTRAINT assets_status_check CHECK (status IN ('OFFLINE','AVAILABLE','RESERVED','RUNNING','DEGRADED','ERROR'));
ALTER TABLE reservations ADD COLUMN IF NOT EXISTS token_hash TEXT, ADD COLUMN IF NOT EXISTS released_at TIMESTAMPTZ;
ALTER TABLE reservations DROP CONSTRAINT IF EXISTS reservations_status_check;
ALTER TABLE reservations ADD CONSTRAINT reservations_status_check CHECK (status IN ('ACTIVE','RELEASED','EXPIRED','CANCELLED'));
ALTER TABLE workflows ADD COLUMN IF NOT EXISTS description TEXT NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS version INTEGER NOT NULL DEFAULT 1, ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ NOT NULL DEFAULT now();
ALTER TABLE workflow_runs ADD COLUMN IF NOT EXISTS trigger_source TEXT NOT NULL DEFAULT 'api', ADD COLUMN IF NOT EXISTS git_sha TEXT, ADD COLUMN IF NOT EXISTS artifact_ref TEXT;
ALTER TABLE workflow_runs DROP CONSTRAINT IF EXISTS workflow_runs_status_check;
ALTER TABLE workflow_runs ADD CONSTRAINT workflow_runs_status_check CHECK (status IN ('QUEUED','PREPARING','RUNNING','CLEANING_UP','PASSED','FAILED','CANCELLED','TIMED_OUT'));
ALTER TABLE workflow_steps ADD COLUMN IF NOT EXISTS command TEXT NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS duration_ms BIGINT;
ALTER TABLE workflow_steps DROP CONSTRAINT IF EXISTS workflow_steps_phase_check;
ALTER TABLE workflow_steps ADD CONSTRAINT workflow_steps_phase_check CHECK (phase IN ('prepare','deploy','configure','test','collect','cleanup','setup'));
ALTER TABLE workflow_steps DROP CONSTRAINT IF EXISTS workflow_steps_status_check;
ALTER TABLE workflow_steps ADD CONSTRAINT workflow_steps_status_check CHECK (status IN ('PENDING','RUNNING','PASSED','FAILED','CANCELLED','TIMED_OUT'));
ALTER TABLE logs DROP CONSTRAINT IF EXISTS logs_stream_check;
ALTER TABLE logs ADD CONSTRAINT logs_stream_check CHECK (stream IN ('stdout','stderr','system'));
CREATE TABLE IF NOT EXISTS artifacts (id UUID PRIMARY KEY, run_id UUID NOT NULL REFERENCES workflow_runs(id) ON DELETE CASCADE, step_id UUID REFERENCES workflow_steps(id) ON DELETE SET NULL, name TEXT NOT NULL, path TEXT NOT NULL, content_type TEXT NOT NULL, size_bytes BIGINT NOT NULL, storage_path TEXT NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS artifacts_run_idx ON artifacts(run_id, created_at);
CREATE TABLE IF NOT EXISTS audit_events (id BIGSERIAL PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_events_created_idx ON audit_events(created_at DESC);
